declare var React;
declare var $;
declare var ReactDOM;
declare var ReactBootstrap;

const SkillsGrid = React.createClass({
    getInitialState() {
        return {
            skills: [],
            version: ''
        };
    },

    onListSkills() {

        $.getJSON(`http://${location.host}/version`, (data) => {
            this.setState({
                version: data.version
            });
        });

        $.getJSON(`http://${location.host}/skill/list`, (response) => {
            this.setState({
                skills: response.skills
            });
        });
    },

    onLaunch(record) {
        const command = JSON.stringify({
            command: record.name
        });
        $.post(`http://${location.host}/launch-dev`, command, (response)=> {
            this.onListSkills();
        });
    },

    onStop(record) {
        const command = JSON.stringify({
            command: record.name
        });
        $.post(`http://${location.host}/terminate`, command, (response) => {
            this.onListSkills();
        });
    },

    launchConsole() {
        $.getJSON(`http://${location.host}/devtools`, (data) => {
            const frontEnd = data[0].devtoolsFrontendUrl.replace('127.0.0.1', location.hostname);
            window.open(`http://${location.hostname}:9191${frontEnd}`, "_blank");
        });
    },

    launchSSMConsole() {
        $.getJSON(`http://${location.host}/ssm-devtools`, (data) => {
            const frontEnd = data[0].devtoolsFrontendUrl.replace('127.0.0.1', location.hostname);
            window.open(`http://${location.hostname}:12345${frontEnd}`, "_blank");
        });
    },

    componentDidMount() {
        this.onListSkills();
    },

    render() {
        let skills = [];
        this.state.skills.forEach((record) => {
            if(!record.running) {
                skills.push(<ReactBootstrap.ListGroupItem>
                    <div className="row">
                        <div className="col-xs-6 col-sm-8 col-md-10">
                            <h4>{record.name} <small>v{record.version}</small></h4>
                        </div>
                        <div className="col-xs-6 col-sm-4 col-md-2">
                            <ReactBootstrap.Button bsStyle="success" className="btn-block" onClick={() => {
                                this.onLaunch(record);
                            }}>
                                <span className="glyphicon glyphicon-play"></span>&nbsp;
                                <span>Launch</span>
                            </ReactBootstrap.Button>
                        </div>
                    </div>
                </ReactBootstrap.ListGroupItem>);
            }
            else {
                skills.push(<ReactBootstrap.ListGroupItem>
                    <div className="row">
                        <div className="col-xs-6 col-sm-8 col-md-10">
                            <h4>{record.name} <small>v{record.version}</small></h4>
                        </div>
                        <div className="col-xs-6 col-sm-4 col-md-2">
                            <ReactBootstrap.ButtonGroup className="running">
                                <ReactBootstrap.Button bsStyle="danger" onClick={() => {
                                    this.onStop(record);
                                }}>
                                    <span className="glyphicon glyphicon-stop"></span>&nbsp;
                                </ReactBootstrap.Button>
                                <ReactBootstrap.Button bsStyle="default" onClick={this.launchConsole}>
                                    <span className="glyphicon glyphicon-cog"></span>&nbsp;
                                </ReactBootstrap.Button>
                            </ReactBootstrap.ButtonGroup>
                        </div>
                    </div>
                </ReactBootstrap.ListGroupItem>);
            }
        });
        return <div className="row">
            <div className="col-sm-12">
                <h1 className="pull-left" style={{marginBottom:20}}>Skills Manager <span className="version">v{this.state.version}</span></h1>
                <div className="pull-right" style={{paddingTop:20}}>
                    <ReactBootstrap.ButtonGroup>
                        <ReactBootstrap.Button bsStyle="default" onClick={this.onListSkills}>
                            <span className="glyphicon glyphicon-refresh"></span>&nbsp;
                            <span>Refresh</span>
                        </ReactBootstrap.Button>
                        <ReactBootstrap.Button bsStyle="default" onClick={this.launchSSMConsole}>
                            <span className="glyphicon glyphicon-cog"></span>&nbsp;
                            <span>Debug</span>
                        </ReactBootstrap.Button>
                    </ReactBootstrap.ButtonGroup>
                </div>
                <div className="clearfix"></div>
                <ReactBootstrap.ListGroup>{skills}</ReactBootstrap.ListGroup>
            </div>
        </div>;
    }
});

$(document).ready(() => {
    ReactDOM.render(<SkillsGrid/>, document.getElementById('grid'));
});
